// Fan out table names as separate items
// Streamlit sends: { tables: ['sales', 'products'] }
const body = $input.first().json.body;
const tables = body.tables;

if (!tables || !Array.isArray(tables) || tables.length === 0) {
  throw new Error('No tables provided. Send: { tables: ["table1", "table2"] }');
}

return tables.map(name => ({ json: { table_name: name } }));

