const raw = $input.first().json.choices[0].message.content.trim();

let parsed;
try {
  const cleaned = raw
    .replace(/```json\n?/g, '')
    .replace(/```\n?/g, '')
    .trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  // Groq didn't return clean JSON — wrap it
  return [{
    json: {
      success: false,
      error: 'Groq returned invalid JSON',
      raw_response: raw,
      summary_text: raw,
      key_metrics: [],
      anomalies: [],
      chart_data: []
    }
  }];
}

return [{
  json: {
    success: true,
    summary_text:  parsed.summary_text  || '',
    key_metrics:   parsed.key_metrics   || [],
    anomalies:     parsed.anomalies     || [],
    chart_data:    parsed.chart_data    || [],
    raw_stats:     $('Aggregate Stats').item.json.all_stats
  }
}];
